	private static final class LazyDistinctCountIteration implements CloseableIteration<BindingSet> {
		private final DistinctCountPlan plan;
		private final TupleEvaluator evaluator;
		private final Object lock = new Object();
		private boolean initialized;
		private boolean closed;
		private boolean nextReady;
		private BindingSet next;
		private CloseableIteration<? extends BindingSet> delegate;

		private LazyDistinctCountIteration(DistinctCountPlan plan, TupleEvaluator evaluator) {
			this.plan = plan;
			this.evaluator = evaluator;
		}

		@Override
		public boolean hasNext() throws QueryEvaluationException {
			synchronized (lock) {
				if (nextReady) {
					return true;
				}
				if (closed) {
					return false;
				}
			}
			try {
				BindingSet candidate = readNext();
				synchronized (lock) {
					if (closed) {
						next = null;
						nextReady = false;
					} else {
						next = candidate;
						nextReady = candidate != null;
					}
				}
				if (candidate == null) {
					close();
					return false;
				}
				return !isClosed();
			} catch (IOException e) {
				close();
				throw new QueryEvaluationException(e);
			} catch (QueryEvaluationException e) {
				close();
				throw e;
			}
		}

		private BindingSet readNext() throws QueryEvaluationException, IOException {
			if (!initialized) {
				initialized = true;
				TupleExpr rewritten = plan.rewrite(this::isCancelled);
				if (rewritten == null || isCancelled()) {
					return null;
				}
				CloseableIteration<? extends BindingSet> candidate = evaluator.evaluate(rewritten);
				synchronized (lock) {
					if (closed) {
						candidate.close();
						return null;
					}
					delegate = candidate;
				}
			}

			CloseableIteration<? extends BindingSet> current;
			synchronized (lock) {
				if (closed) {
					return null;
				}
				current = delegate;
			}
			if (current == null || !current.hasNext()) {
				return null;
			}
			return current.next();
		}

		private boolean isCancelled() {
			return isClosed() || Thread.currentThread().isInterrupted();
		}

		@Override
		public BindingSet next() throws QueryEvaluationException {
			if (!hasNext()) {
				throw new NoSuchElementException();
			}
			synchronized (lock) {
				if (closed || !nextReady) {
					throw new NoSuchElementException();
				}
				BindingSet result = next;
				next = null;
				nextReady = false;
				return result;
			}
		}

		@Override
		public void close() {
			CloseableIteration<? extends BindingSet> current;
			synchronized (lock) {
				if (closed) {
					return;
				}
				closed = true;
				current = delegate;
				delegate = null;
				next = null;
				nextReady = false;
			}
			try {
				plan.close();
			} finally {
				if (current != null) {
					current.close();
				}
			}
		}

		private boolean isClosed() {
			synchronized (lock) {
				return closed;
			}
		}
	}

	static boolean hasNoGraphs(Dataset dataset) {
		return dataset == null || (dataset.getDefaultGraphs().isEmpty() && dataset.getNamedGraphs().isEmpty());
	}

	private static TupleExpr unwrapRoot(TupleExpr tupleExpr) {
		return tupleExpr instanceof QueryRoot ? ((QueryRoot) tupleExpr).getArg() : tupleExpr;
	}

	/**
	 * The constant values and variable names of a statement pattern in the default context scope, or {@code null} when
	 * the pattern cannot be served by a prefix-run scan (named-graph scope or a variable used more than once).
	 */
	private static final class PatternFields {
		final Resource subj;
		final IRI pred;
		final Value obj;
		final Resource context;
		private final String[] varNames = new String[4];

		private PatternFields(Resource subj, IRI pred, Value obj, Resource context) {
			this.subj = subj;
			this.pred = pred;
			this.obj = obj;
			this.context = context;
		}

		static PatternFields of(StatementPattern pattern) {
			if (pattern.getScope() != StatementPattern.Scope.DEFAULT_CONTEXTS) {
				return null;
			}
			Var subjVar = pattern.getSubjectVar();
			Var predVar = pattern.getPredicateVar();
			Var objVar = pattern.getObjectVar();
			Var ctxVar = pattern.getContextVar();
			Value subj = subjVar.getValue();
			Value pred = predVar.getValue();
			Value obj = objVar.getValue();
			Value ctx = ctxVar == null ? null : ctxVar.getValue();
			if ((subj != null && !(subj instanceof Resource)) || (pred != null && !(pred instanceof IRI))
					|| (ctx != null && !(ctx instanceof Resource))) {
				return null;
			}
			PatternFields fields = new PatternFields((Resource) subj, (IRI) pred, obj, (Resource) ctx);
			if (!fields.bind(TripleIndex.SUBJ_IDX, subjVar) || !fields.bind(TripleIndex.PRED_IDX, predVar)
					|| !fields.bind(TripleIndex.OBJ_IDX, objVar) || !fields.bind(TripleIndex.CONTEXT_IDX, ctxVar)) {
				return null;
			}
			return fields;
		}

		private boolean bind(int field, Var var) {
			if (var == null || var.hasValue()) {
				return true;
			}
			if (Arrays.asList(varNames).contains(var.getName())) {
				return false;
			}
			varNames[field] = var.getName();
			return true;
		}

		Integer fieldOf(String varName) {
			for (int field = 0; field < varNames.length; field++) {
				if (varName.equals(varNames[field])) {
					return field;
				}
			}
			return null;
		}
	}
